def _kernel(x, width, quadratic=0.0):
    from scipy.spatial.distance import cdist
    ip = x @ x.T
    return 1.0 + ip + 2 * np.exp(-width * cdist(x, x, 'sqeuclidean')) + quadratic * (ip * ip)

def poly(q, m):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(q[:, i], axis=1) for d in range(1, m + 1) for i in combinations_with_replacement(range(q.shape[1]), d)])
